     1	package com.pousada.marealta.notification;
     2	
     3	import com.pousada.marealta.model.Reservation;
     4	import com.pousada.marealta.service.MessageService;
     5	import com.pousada.marealta.util.FormatHelper;
     6	
     7	public class GuestEmailHandler implements NotificationHandler {
     8	    private final MessageService messageService;
     9	
    10	    public GuestEmailHandler(MessageService messageService) {
    11	        this.messageService = messageService;
    12	    }
    13	
    14	    @Override
    15	    public void handleConfirmation(Reservation reservation) {
    16	        String receipt = buildReceipt(reservation);
    17	        String body = buildEmail(reservation, receipt);
    18	
    19	        messageService.sendMessage(
    20	            "EMAIL",
    21	            reservation.guestEmail,
    22	            "Reserva confirmada - Pousada Maré Alta",
    23	            body
    24	        );
    25	    }
    26	
    27	    @Override
    28	    public void handleCancellation(Reservation reservation) {
    29	    }
    30	
    31	    private String buildReceipt(Reservation reservation) {
    32	        StringBuilder receipt = new StringBuilder();
    33	        receipt.append("Comprovante de reserva nº ").append(reservation.id).append("\n");
    34	        receipt.append("Hóspede: ").append(reservation.guestName)
    35	            .append(" (CPF ").append(reservation.guestCpf).append(")\n");
    36	        receipt.append("Quarto: ").append(reservation.roomNumber)
    37	            .append(" (").append(getRoomType(reservation.roomNumber)).append(")\n");
    38	        receipt.append("Entrada: ").append(FormatHelper.formatBrDate(reservation.checkIn))
    39	            .append(" | Saída: ").append(FormatHelper.formatBrDate(reservation.checkOut))
    40	            .append(" | ").append(reservation.nights).append(reservation.nights == 1 ? " diária" : " diárias").append("\n");
    41	        receipt.append("Diárias: ").append(FormatHelper.formatCurrency(reservation.subtotal)).append("\n");
    42	
    43	        if (reservation.discount.signum() > 0) {
    44	            receipt.append("Desconto: ").append(FormatHelper.formatCurrency(reservation.discount)).append("\n");
    45	        }
    46	
    47	        receipt.append("Total: ").append(FormatHelper.formatCurrency(reservation.total)).append("\n");
    48	
    49	        return receipt.toString();
    50	    }
    51	
    52	    private String getRoomType(int roomNumber) {
    53	        return switch (roomNumber) {
    54	            case 101, 102 -> "STANDARD";
    55	            case 201, 202 -> "DELUXE";
    56	            case 301 -> "SUITE";
    57	            default -> "UNKNOWN";
    58	        };
    59	    }
    60	
    61	    private String buildEmail(Reservation reservation, String receipt) {
    62	        return "Olá, " + reservation.guestName + "!\n\n" +
    63	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
    64	            receipt + "\n" +
    65	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
    66	            "Até breve!";
    67	    }
    68	}
