     3	import io.javalin.Javalin;
     4	
     5	import com.pousada.marealta.api.ReservationController;
     6	import com.pousada.marealta.notification.FinanceNotificationHandler;
     7	import com.pousada.marealta.notification.GoveranceNotificationHandler;
     8	import com.pousada.marealta.notification.GuestEmailHandler;
     9	import com.pousada.marealta.notification.NotificationService;
    10	import com.pousada.marealta.service.MessageService;
    11	import com.pousada.marealta.service.OccupancyReportService;
    12	import com.pousada.marealta.service.ReservationService;
    13	import com.pousada.marealta.service.RevenueReportService;
    14	import com.pousada.marealta.service.RoomService;
    15	
    16	public class Application {
    17	    public static void main(String[] args) {
    18	        String portStr = System.getenv("PORT");
    19	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
    20	
    21	        RoomService roomService = new RoomService();
    22	        MessageService messageService = new MessageService();
    23	        NotificationService notificationService = new NotificationService();
    24	
    25	        notificationService.registerHandler(new GuestEmailHandler(messageService));
    26	        notificationService.registerHandler(new GoveranceNotificationHandler(messageService));
    27	        notificationService.registerHandler(new FinanceNotificationHandler(messageService));
    28	
    29	        ReservationService reservationService = new ReservationService(roomService, notificationService);
    30	        OccupancyReportService occupancyReportService = new OccupancyReportService(reservationService, roomService);
    31	        RevenueReportService revenueReportService = new RevenueReportService(reservationService);
    32	
    33	        ReservationController controller = new ReservationController(
    34	            roomService, reservationService, messageService, occupancyReportService, revenueReportService
    35	        );
    36	
    37	        Javalin app = Javalin.create();
    38	
    39	        controller.registerRoutes(app);
    40	
    41	        app.start(port);
    42	    }
    43	}

