    26	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    27	                                         LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    28	        Optional<Room> room = roomService.getRoomByNumber(roomNumber);
    29	        if (room.isEmpty()) {
    30	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
    31	        }
    32	
    33	        Room r = room.get();
    34	
    35	        if (guests < 1 || guests > r.getCapacity()) {
    36	            throw new IllegalArgumentException(
    37	                guests > r.getCapacity() ? "CAPACITY_EXCEEDED" : "INVALID_REQUEST"
    38	            );
    39	        }
    40	
    41	        if (!checkOut.isAfter(checkIn)) {
    42	            throw new IllegalArgumentException("INVALID_REQUEST");
    43	        }
    44	
    45	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
    46	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    47	        }
    48	
    49	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    50	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(r.getNightlyRate(), checkIn, checkOut);
    51	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
    52	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
    53	
    54	        Reservation reservation = new Reservation(
    55	            nextReservationId++, roomNumber, guestName, guestEmail, guestCpf,
    56	            checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total
    57	        );
    58	
    59	        reservations.add(reservation);
    60	        return reservation;
    61	    }
    62	
    63	    public Optional<Reservation> getReservation(long id) {
    64	        return reservations.stream()
    65	            .filter(r -> r.id == id)
    66	            .findFirst();
    67	    }
    68	
    69	    public Reservation confirmReservation(long id, BigDecimal amountPaid) {
    70	        Reservation reservation = getReservation(id)
    71	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
    72	
    73	        if (reservation.status != ReservationStatus.PENDING) {
    74	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    75	        }
    76	
    77	        reservation.status = ReservationStatus.CONFIRMED;
    78	        reservation.amountPaid = amountPaid;
    79	
    80	        notificationService.notifyConfirmation(reservation);
    81	
    82	        return reservation;
    83	    }
    84	
    85	    public Reservation cancelReservation(long id) {
    86	        Reservation reservation = getReservation(id)
    87	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
    88	
    89	        if (reservation.status == ReservationStatus.CHECKED_IN ||
    90	            reservation.status == ReservationStatus.CHECKED_OUT ||
    91	            reservation.status == ReservationStatus.CANCELLED) {
    92	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    93	        }
    94	
    95	        boolean wasConfirmed = reservation.status == ReservationStatus.CONFIRMED;
    96	        reservation.status = ReservationStatus.CANCELLED;
    97	
    98	        if (wasConfirmed) {
    99	            if (reservation.ratePlan == RatePlan.STANDARD) {
   100	                reservation.refund = reservation.amountPaid;
   101	            } else {
   102	                reservation.refund = BigDecimal.ZERO;
   103	            }
   104	            notificationService.notifyCancellation(reservation);
   105	        }
   106	
   107	        return reservation;
   108	    }
   109	
   110	    public Reservation checkIn(long id) {
   111	        Reservation reservation = getReservation(id)
   112	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
   113	
   114	        if (reservation.status != ReservationStatus.CONFIRMED) {
   115	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   116	        }
   117	
   118	        reservation.status = ReservationStatus.CHECKED_IN;
   119	        return reservation;
   120	    }
   121	
   122	    public Reservation checkOut(long id) {
   123	        Reservation reservation = getReservation(id)
   124	            .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
   125	
   126	        if (reservation.status != ReservationStatus.CHECKED_IN) {
   127	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   128	        }
   129	
   130	        reservation.status = ReservationStatus.CHECKED_OUT;
   131	        return reservation;
   132	    }
   133	
   134	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   135	        LocalDate current = checkIn;
   136	
   137	        while (current.isBefore(checkOut)) {
   138	            LocalDate finalCurrent = current;
   139	            boolean unavailable = reservations.stream()
   140	                .filter(r -> r.roomNumber == roomNumber && r.status != ReservationStatus.CANCELLED)
   141	                .anyMatch(r -> {
   142	                    LocalDate resStart = r.checkIn;
   143	                    LocalDate resEnd = r.checkOut;
   144	                    return !finalCurrent.isBefore(resStart) && finalCurrent.isBefore(resEnd);
   145	                });
   146	
   147	            if (unavailable) return true;
   148	            current = current.plusDays(1);
   149	        }
   150	
   151	        return false;
   152	    }
