     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import com.pousada.marealta.model.RatePlan;
     7	
     8	public class PriceCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    11	
    12	    public static BigDecimal roundPrice(BigDecimal value) {
    13	        return value.setScale(2, RoundingMode.HALF_EVEN);
    14	    }
    15	
    16	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
    17	        if (SeasonHelper.isHighSeason(date)) {
    18	            return roundPrice(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
    19	        }
    20	        return baseRate;
    21	    }
    22	
    23	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    24	        BigDecimal subtotal = BigDecimal.ZERO;
    25	        LocalDate current = checkIn;
    26	
    27	        while (current.isBefore(checkOut)) {
    28	            BigDecimal nightlyRate = calculateNightlyRate(baseRate, current);
    29	            subtotal = subtotal.add(nightlyRate);
    30	            current = current.plusDays(1);
    31	        }
    32	
    33	        return roundPrice(subtotal);
    34	    }
    35	
    36	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    37	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    38	            return roundPrice(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    39	        }
    40	        return BigDecimal.ZERO;
    41	    }
    42	
    43	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    44	        return roundPrice(subtotal.subtract(discount));
    45	    }
    46	}
