    20	    public String generateOccupancyReport(LocalDate date) {
    21	        StringBuilder csv = new StringBuilder();
    22	        csv.append("room,type,reservation,check_in,check_out\n");
    23	
    24	        List<Reservation> occupiedRooms = new ArrayList<>();
    25	
    26	        for (Room room : roomService.getAllRooms()) {
    27	            for (Reservation res : reservationService.getAllReservations()) {
    28	                if (res.roomNumber == room.number &&
    29	                    res.status != ReservationStatus.CANCELLED &&
    30	                    (res.status == ReservationStatus.CONFIRMED || res.status == ReservationStatus.CHECKED_IN ||
    31	                     res.status == ReservationStatus.CHECKED_OUT)) {
    32	                    if (!date.isBefore(res.checkIn) && date.isBefore(res.checkOut)) {
    33	                        occupiedRooms.add(res);
    34	                    }
    35	                }
    36	            }
    37	        }
    38	
    39	        occupiedRooms.sort((a, b) -> Integer.compare(a.roomNumber, b.roomNumber));
    40	
    41	        for (Reservation res : occupiedRooms) {
    42	            Room room = roomService.getRoomByNumber(res.roomNumber).get();
    43	            csv.append(res.roomNumber).append(",")
    44	                .append(room.type.name).append(",")
    45	                .append(res.id).append(",")
    46	                .append(FormatHelper.formatIsoDate(res.checkIn)).append(",")
