    24	        List<Reservation> relevantReservations = new ArrayList<>();
    25	        BigDecimal total = BigDecimal.ZERO;
    26	
    27	        for (Reservation res : reservationService.getAllReservations()) {
    28	            YearMonth resMonth = YearMonth.from(res.checkIn);
    29	            if (resMonth.equals(month)) {
    30	                BigDecimal amount = res.amountPaid;
    31	                if (res.refund != null) {
    32	                    amount = amount.subtract(res.refund);
