    36	                    relevantReservations.add(res);
    37	                    total = total.add(amount);
    38	                }
    39	            }
    40	        }
    41	
    42	        relevantReservations.sort((a, b) -> {
    43	            int dateCompare = a.checkIn.compareTo(b.checkIn);
    44	            if (dateCompare != 0) return dateCompare;
    45	            return Long.compare(a.id, b.id);
    46	        });
    47	
    48	        for (Reservation res : relevantReservations) {
    49	            BigDecimal amount = res.amountPaid;
    50	            if (res.refund != null) {
    51	                amount = amount.subtract(res.refund);
    52	            }
    53	
    54	            csv.append(res.id).append(",")
    55	                .append(res.roomNumber).append(",")
    56	                .append(FormatHelper.formatIsoDate(res.checkIn)).append(",")
    57	                .append(FormatHelper.formatIsoDate(res.checkOut)).append(",")
